BEGIN READ ONLY;
SET LOCAL statement_timeout='5s';
SELECT current_database() = 'postgres' AS expected_database;
SELECT coalesce(last_failure_stage,'none') AS failure_stage, count(*) AS transactions,
 count(*) FILTER (WHERE completed_at IS NOT NULL) AS completed,
 count(*) FILTER (WHERE result_issuer IS NOT NULL) AS result_checkpointed,
 max(attempt_count) AS max_attempts
 FROM academy.identity_authorization_transaction
 WHERE created_at >= '2026-09-08 04:21:00+00'::timestamptz
   AND created_at < '2026-09-08 04:24:00+00'::timestamptz
 GROUP BY last_failure_stage ORDER BY last_failure_stage NULLS FIRST;
ROLLBACK;
